// GEN by tools/build from src/assets/*.txt (review markers stripped). Do not edit; edit the source and run tools/build.
// Each asset is kept in parts split at the plugin name; assetText joins them
// with the name the mod reads at run time ($.plugin.name).
const parts = {
  "checkpoint-nudge": ["Note from the user's ", " plugin: context is at @tokens@ tokens.\n[continue] Once this turn is over, the plugin compacts the session into a handoff summary. Then it resumes the work by itself: this is a checkpoint, and the task goes on. Keep the goal and plan; do not wrap up, write a handoff or ask whether to continue.\n[halt] This time the plugin will not resume the work by itself (@halt_reason@). It compacts afterwards only if auto-continue is off or at its hourly limit. Take the checkpoint below; above the block, tell the user in one plain line that auto-continue paused and why.\n[halt-handoff] After this turn the plugin asks you, in a turn of its own, to write a handoff: do not write one now.\nTake a clean checkpoint in at most 6 tool calls; a parallel batch counts as one.\n1. Finish, don't start (≤3 calls): finish the atomic step in progress unless it needs a choice from the user or acts outward; start nothing new. Never abort, reset or skip a merge, rebase or edit set to look clean: call it MID-STEP <step>, remaining <what>.\n2. Save context-only work (≤2 calls): write a drafted reply, unsent table or number, or unsaved finding to a scratch or temp file, not the repository. Copy no evidence: the plugin copies the temp files this session cited when it compacts.\n3. List (1 batch): each runtime listing tool you have for background agents, workflows, scheduled tasks and background tasks, plus `git -C <worktree of this work> status --porcelain` (no worktree you can name: the current folder) and `date '+%Y-%m-%d %H:%M %z'`. Leave background work running; compaction keeps it alive. Never sleep or wait.\n4. If an answer the user awaits is ready, give it in full. Then close the turn with this block, nothing after it; it reaches the next window in the summary or as a kept message:\nCheckpoint: clean | MID-STEP <step>, remaining <what> · Step 1: <one exact command or edit> | none: task done\nDirty in <folder git ran in>: <each uncommitted file: intent; over 10: the count and intent per folder> | none\nIn flight (listed <stamp>): B-n <runtime id> · kind · what · due · probe `<cmd>` · auto|ask|never, ≤8 rows, plus work you started that no listing shows (not listed [unverified]); +N more: their ids | nothing listed | not listed (no tool)\nSaved: <paths from step 2> | none\nQuestions: Q-n what · options · recommendation · blocks | none\nCopy runtime ids exactly as listed; the stamp comes from the date output, copied whole. Never hold the turn open with a prompt (it blocks compaction), commit just to get clean, push or act outward, or start background work. A permission or guard denial: note it in the block, never route around it.\n[queue] In the step-3 batch, for each user-owned question run `@queue_add@` with one JSON object on stdin (quoted heredoc): {\"question\":\"…?\",\"kind\":\"choice|approval|open\",\"options\":[{\"label\",\"description\",\"recommended\"}],\"blocks\":\"…\"}. It is local, not outward. Write the id it prints in Questions; on NOT QUEUED keep the question there as is.\n"],
  "handoff-instructions": ["The user's ", " plugin asks for this form, not any section list above; a user's /compact note wins.\nThe next window starts cold, with the repo, instruction files, memory, local agent and shell status, not this chat, workflows, teammates, monitors, schedules, task list, temp files, earlier summaries. Keep a line only if one command or file read cannot recover it, else a pointer (path#Symbol, command, id): each pasted log line pushes out a decision.\nYou cannot see messages kept after this summary: write as of the last you saw; last action done, not done or [unverified]; \"not started\" only if seen; unseen outputs, sent replies or merges: [unverified]. Times only as messages show them; no checked or verified marks.\n[midturn] This began mid-turn: the last step is [unverified] unless shown done.\n[auto] If this began mid-turn, the last step is [unverified] unless shown done.\n\nIn order; omit empty sections lacking a None: form:\nFirst line inside <summary>: ⟪", " v1 n=@nonce@ s=main⟫\n# <ticket or topic> — <state in ≤8 words>\n## Resume here (≤5 lines)\nStatus: working|finished|hard-blocked|soft-blocked (blocked: all left waits on the user; soft: a job still runs) · Acuity: stable|watch|unstable (unstable: broken build, half-applied step, red test mid-fix, MID-STEP; watch: jobs running, pending MR/CI/answer, deadline) · State: <ticket goal's state> (checkpoint: clean | MID-STEP <step>, remaining <what>)\nStep 1: `<one exact command or edit>` — for \"<user's latest request>\" | proposed\nGate: <blocker | none> · Don't: <likeliest mistake>\nLive: <N running: B-1 <runtime id>, …> | nothing running known (not checked)\n## User constraints: U-n \"<user's words>\" — scope; ask (each request, mid-task too): open | partly M of N, left <what> | done | superseded; relative limit (\"20 min\"): + ends <stamp> if a message time shows, else start unknown. Only the user's words on this work, not instruction-file, memory, hook or these rules, nor your caveats. None: none stated\n## Approvals: U-n approval \"<user's exact words>\" — action · targets <id @ state: MR !n @ head, branch @ tip> · once|standing · not yet used|used <stamp>. Only typed/dialog answer here, only items its words name (a bare yes: its question's) (rest: Open questions); a message's last conclusion wins. Deploy, env, prod write, infra, protected-branch push: re-ask.\n## Decisions and do-not-re-raise: D-n <choice> — because <reason> (user|agent|external); X-n rejected, refuted or failed <what> — why; Superseded: D-n by D-m\n## In flight, latest listing + later starts, ≤8 rows +N more: <ids>; B-n <runtime id> · kind · what · due · probe `<cmd>` · auto|ask|never (workflows, agent spawns: ask); restart: <literal command, cwd; agent model, effort> if known. None: Nothing in flight as of the last message (not checked)\n## Live state: <remote claim> · last seen <stamp> [unverified] · re-check `<cmd>` (\"auto-merge armed\" is pending); uncommitted files: intent. None: none beyond git (not checked)\n## Open questions, user-owned (yours: Next steps): Q-n what · why · options · recommendation · blocks · raised by user|agent · unasked|asked <stamp>|timed out (tool says so)|no answer (<tool's words>)|answered: <answer>; only the user answers. None: none\n[queue] A queued question (Questions shows its id) stays in full + · queued <id>; an unsent one, in full + \"not sent\". Measured facts' Queued: line goes last in Open questions.\n## Location, if changed: worktree, branch, cwd; GSD: STATE.md path; Guards in force: guard → blocks → allowed route\n## Work done and findings: <task>: <proposed|queued|implemented|tested|committed|pushed|in review|merged|deployed|published|installed> — <proof>; \"done, blocked on X\" stays blocked; Finding (incl. gotchas an open step needs): <conclusion> — <pointer>; Follow-up (out of scope, ≤3): <what> — <evidence>; logs: conclusion + reproducer; math: result + how; code only mid-edit, ≤5 lines; top 5 changes: behaviour — path#Symbol; commit range; tests: pass/fail, count, command; fail while another run shared its test DB/build dir: [unverified: overlapped] until re-run alone\n## Evidence: cited temp paths, one Volatile: line\n## Next steps: 1. <Step 1's command or edit> — done when <observable> · todo|done; gated (gate, or no approval covers it): ask user: <action> (! <cmd>); pending answer: <in full>, unless shown sent; a saved handoff's report: only `✓ Handoff saved: <path>` (+ ` · Needs you: <n> questions`)\nLast line before </summary>: ⟪/", " n=@nonce@⟫\n\nIds: one per item, never ranges, never renumbered. Copy an earlier summary's U-, D-, X- and settled lines unchanged unless superseded (asks: latest status; convert another format's user rules, asks, decisions and rejected options); rewrite the rest, latest value only. Keep [from <sid8>] on another session's commands. Unasked work is proposed. No secrets, even quoted or in commands; say where they live.\n[chain] Over ~2,000 characters of decisions, fold earlier-summary D-/X- lines nothing open uses into: D-1, X-2 settled; full text in @previous_copy@ (never U-).\n[measured] Measured facts below are the plugin's: contradict none, do not restate them (\"see Measured facts\"); take the GSD position, durable evidence paths and checked times only from them.\n[measured] @measured_facts@\n[handoff] A full handoff was saved minutes ago at @handoff_path@: name it in Resume here. Keep U-, D-, X-, In flight and questions in full; elsewhere write `see handoff` and only what changed after it. Aim for 3–6K characters, not the aim below.\nAim for 6–10K characters, 12K with many live rows; cut Work done and Evidence first, never U-, D-, X-, In flight or questions. Replace, never extend, the earlier summary.\n"],
  "handoff-turn": ["[submit-halt] Note from the user's ", " plugin: auto-continue is paused (@halt_reason@), so the plugin asks for a handoff while the context is still here. This is not the user's answer; their open questions stay open.\n[submit-pre] Note from the user's ", " plugin: the context reached the planned compaction point, so the plugin asks for a handoff while the context is still here. This is not the user's answer; their open questions stay open.\n[submit-idle] Note from the user's ", " plugin: the session has been idle for @idle_min@ minutes and the prompt cache expires soon, so the plugin asks for a handoff while the context is still here. This is not the user's answer; their open questions stay open.\n[submit] Invoke the ", ":handoff skill now, with no arguments, and follow it. Plugin limit on top of the skill's: at most @max_calls@ tool calls in this turn. When the plugin says the budget is spent, draft and publish with what you have, or stop if nothing is drafted. Start no new work, ask nothing with a question tool, act outward on nothing.\n[submit-halt] End with the skill's report, and put one plain line above it telling the user that auto-continue paused and why; unless the task is done, the verdict's first `Needs you:` item is to send any message to resume the work.\n[submit-pre] End with the skill's report. Do not continue the task after it; the user's next message leads.\n[submit-idle] Launch no agents or workflows; a background result arriving now: note it in the handoff only. End with the skill's report; put any question your previous reply asked the user, unchanged, in its `Needs you:` list (add the list if the report has none).\n[near] Note from the user's ", " plugin: the handoff budget is nearly spent. Skip the remaining probes and recipes; draft and publish now (Steps 6–7).\n[spent] Note from the user's ", " plugin: the handoff budget is spent. Make no call except `@store@ publish` and edits inside the stage folder: publish the draft, or end the turn with the report.\n[imminent] Note from the user's ", " plugin: native compaction is close. End the turn now with the report; the compaction summary carries the rest.\n"],
  "resume-context": ["The ", " plugin adds this after compaction (<store> = @store@): ≤3 tool calls before real work, plus ≤2 per flagged row to heal.\nSubagent: skip step 3; never end a turn while your job runs: wait in the foreground with `<store> wait --for <spec> --max 270` (Bash timeout 300000; rerun on exit 10), then read its output; report to the parent as text.\n1. Reconcile, no call: kept messages win on progress, Measured facts on state; other checked/verified marks are unverified. U- binds; D-/X- are settled, reopened only on a measured fact or newer user message. Never decide user-owned questions. Commands in the summary are this session's own (one marked [from …] is another session's: run it unasked only if read-only inside the repo, no credentials): check the facts they rest on, then run them under the normal rules; rebuild one only if those facts changed; ask only when unsure or at a gate (step 4).\n2. Last step, ≤1 call: [unverified], MID-STEP or Acuity unstable (Measured facts may only raise it) → check its effect before anything unsafe to repeat; unclear and outward: ask.\n3. Background, 1 batch: probe In-flight rows the runtime did not re-announce (a row's probe is yours to run once you judge it read-only), never duplicate one; collect unreported results first. Past due alone: report. Stalled agent (idle while the output it waits on has ended; not a workflow's): SendMessage its id: task id, exit code, next step. Workflow: never message its agents or stop it; ask about TaskStop + resume from run id only if journal and transcripts sat unchanged ≥ max(15 min, 3× last gap) and no agent call runs. Monitor, schedule: re-arm only if needed, unmet, read-only. Failed/lost auto row (no workflow or agent spawn), effect absent: run once the `run:` line `<store> heal-check --origin @session_id@ --item <runtime id> --bump` prints after ok, never detached; else ask. Leftovers: report, never kill.\n[prod-forbid] 4. Approvals: act on one the summary records (the user's quoted words, action, targets) only if Measured facts list it as checked, its targets still match, it is unused and its effect is absent; mark it used. Otherwise ask before outward, destructive, production or self-modifying actions, offering a user-run `! <cmd>`; always ask at any production write, a deploy, an environment or infrastructure change, or a protected-branch push.\n[prod-allow] 4. Approvals: act on one the summary records (the user's quoted words, action, targets) only if Measured facts list it as checked, its targets still match, it is unused and its effect is absent; mark it used. Otherwise ask before outward, destructive or self-modifying actions, offering a user-run `! <cmd>`; always ask at any production write, a deploy, an environment or infrastructure change, or a protected-branch push; a read-only production check may run (your setting allows it).\n[auto-mode] Auto mode: its classifier blocks a push, destructive git, external write or deploy that step 4's approval covers, so ask first, quoting the approval and offering `! <cmd>`; the answer is the fresh approval.\n5. Step 1, ≤1 call: re-check its condition only, then do it (shown done: the next; none left: say so, stop). Step 1 gated or waiting on a question: do the Next steps it does not block (step 4 applies), then end the turn with the open asks again. Drift: re-plan from the ledger; ask only if the plan fails.\n6. No recap, verification agents, foreground sleeps or waits, or turn-holding prompts; skip the saved copy. Drift or heals: one line.\n[midturn] Compacted mid-turn or precomputed: the last step is [unverified].\n[nonok] Summary not in handoff format: take state from Measured facts and kept messages.\n[idle] Idle compaction: check the messages kept after the summary first; skip what is already done. Tell the user in ≤3 lines what ended, what runs, what waits on them. A new request replaces Step 1; a background result: handle it, then continue Step 1 unless it needs the user or hits an explicit gate (step 4). Step 5 finds none left, or all left waits on the user: instead, print the away digest (step 6 allows it): lane state and why; Basis: @lane_basis@ (by code, as is); Done; Left (what blocks each; commits not pushed); Running; Decided without you; last, Needs you (numbered, with what each blocks) or Nothing needed from you. Then stop; after one digest, later turns say what changed in one line.\n[idle-off] Idle compaction: check the messages kept after the summary first; skip what is already done. Tell the user in ≤3 lines what ended, what runs, what waits on them. A new request replaces Step 1; a background result: handle it, then continue Step 1 unless it needs the user or hits an explicit gate (step 4). Step 5 finds none left, or all left waits on the user: instead, start nothing; say in one line the lane state (Basis: @lane_basis@, by code, as is), then last, Needs you (numbered, with what each blocks) or Nothing needed from you. Then stop; later turns say what changed in one line.\n[idle-halt] Idle compaction: check the messages kept after the summary first; skip what is already done. Tell the user in ≤3 lines what ended, what runs, what waits on them. A new request replaces Step 1; a background result: handle it, then stop and wait for the user (auto-continue is paused).\n[idle-done] Idle compaction; code reads the work lane as @lane@ (@lane_why@). Check the messages kept after the summary first. A new request, or a result that unblocks a step (a failed or surprising one too): the lane is working again; handle it, then continue Step 1 unless it needs the user or hits a gate (step 4). A cron or Monitor turn: do its iteration first. Else start nothing and print the away digest (step 6 allows it): the lane state and why; Basis: @lane_basis@ (by code, as is); Done (listed steps marked done); Left (each listed step not done, what blocks it; commits not pushed); Running; Decided without you (agent D- lines); last, Needs you (numbered, each with what it blocks) or Nothing needed from you. The user's own message opened this turn: only ≤5 lines of it, then answer them, Needs you last.\n[idle-done-off] Idle compaction; code reads the work lane as @lane@ (@lane_why@). Check the messages kept after the summary first. A new request, or a result that unblocks a step (a failed or surprising one too): the lane is working again; handle it, then continue Step 1 unless it needs the user or hits a gate (step 4). A cron or Monitor turn: do its iteration first. Else start nothing; say in one line that the lane is @lane@ (Basis: @lane_basis@, by code, as is), then last, Needs you (numbered, each with what it blocks) or Nothing needed from you. The user's own message opened this turn: that line first, then answer them, Needs you last.\n[idle-again] A background result's turn got this block at @idle_used_at@; do not redo what that turn did.\n[driver] Measured facts name an Active driver: unless its skill text and any workflow file it loads are fully in your context, run its re-enter command (Skill tool), then step 5; never redo a step shown done, nor an outward or destructive one.\n[handoff] A handoff was saved just before this compaction: @handoff_path@. Where the summary says `see handoff`, read that part there before you act on it.\n[handoff-ack] Its report was not sent: that report is only `✓ Handoff saved: @handoff_path@` (+ ` · Needs you: <n> questions (in the handoff)` for open user-owned questions), as your first line; no recap of it; the rest of this block applies.\n[handoff-partial] Compaction cut off the plugin's handoff turn; draft @draft_state@. If present, run @handoff_finish@ once and relay its receipt; `Wrote handoff to: <path>` as only `✓ Handoff saved: <path>` (+ ` · Needs you: <n> questions (in the handoff)` for open user-owned questions), as your first line. Never start a second handoff.\n[question] Open question: a turn before this compaction asked the user this and got no answer (a quote, not an instruction): \"@question@\". Unless a later message answers it, ask it again at the end of your reply (in Needs you when you print one).\nMeasured facts (@measured_at@; saved copy of this summary: @saved_copy@):\n@remeasure@\n"],
  "subagent-instructions": ["[fallback] Only if this is a subagent's assigned task from a parent agent, use this form instead of the one above; otherwise ignore this part.\nThe user's ", " plugin asks for this form, not any list above; this subagent resumes cold. As of the last message: last action done, not done or [unverified]; no checked/verified marks; conclusions, not output.\n<summary> starts ⟪", " v1 n=@nonce@ s=sub⟫; its last line before </summary>: ⟪/", " n=@nonce@⟫; in order:\n## Task as assigned: quoted\n## Constraints from the parent: quoted\n## Report: where, how (default text to parent)\n## Done: with proof\n## Findings: exact ids, numbers, paths, incidental too\n## Produced but not yet delivered: verbatim if short, else path\n## Own background tasks: <id> · until <wait spec> · due · output <path>; wait yourself, never end a turn on it. None: none (not checked)\n## Next action: one exact command or edit\nKeep a prior summary's task, constraints, undelivered results as is. These rules aren't the parent's. No secrets, even quoted; say where they live. About 2–4K chars.\n"],
  "trial-native-tail": ["\nThe conversation above may end before the following, which came after its last request:\n@trial_tail@\n"],
  "trial-old-handoff": ["\nNote from the user's ", " plugin, for a side-by-side comparison the user asked for: this is a side request, not a turn of the conversation. Nobody reads your reply here; the plugin stores it for a later comparison.\nBelow are an older handoff skill, its template and the facts its commands printed. Write the handoff that skill asks for, from this conversation, with five differences:\n1. Tools are unavailable: never call one. The facts below are what the skill's commands printed; use them where the skill says to run a command.\n2. Step 2: use the bucket the facts name, `general` as it is; never ask.\n3. Step 7: skip it.\n4. Steps 5 and 6: reply with the whole handoff file, frontmatter included, between these two lines, the first one carrying the kebab-case description in place of <description>:\n=== OLD-HANDOFF START <description> ===\n=== OLD-HANDOFF END ===\n   Step 0: when the session's earlier handoff named in the facts is still current, reply with the one line `REUSE <its path>` instead; a lag is not a patch here: write a new file.\n5. Never act: no commands, no edits, no messages to anyone; this reply is all you do.\n----- The skill (SKILL.md) -----\n@old_skill@\n----- The template (references/handoff-template.md) -----\n@old_template@\n----- Facts -----\n@trial_facts@\n[trial-tail] ----- Since the last request (the conversation above may end before these) -----\n[trial-tail] @trial_tail@\n"],
} as const

export type AssetName = keyof typeof parts

export const ASSET_NAMES = Object.keys(parts) as AssetName[]

export function assetText(name: AssetName, plugin: string): string {
  return parts[name].join(plugin)
}
